node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const subject = 'High Priority: Onboarding Equipment Setup Request';
const content = \`Hello Bob,

I'm writing to request your assistance with an equipment setup for a newly onboarded contractor who is starting soon. As outlined in Olivia's original request to Ethan, the contractor requires the following before start of business on the next business day:

1. Standard Windows laptop — provisioned and ready for use
2. VPN access — configured and credentials provided
3. Email — account set up and fully configured

Please prioritize this request to ensure the contractor can be productive from day one.

Let me know if you need any additional information or if there are any issues meeting this timeline.

Best regards\`;

const fromAddr = 'alice@example.com';
const toAddr = 'bob@example.com';

// Insert into sender's outbox
db.prepare('INSERT INTO ob_emails (email_id, username, from_address, to_address, subject, content, inbox_owner) VALUES (?, ?, ?, ?, ?, ?, ?)').run(
  'alice/' + subject + '.eml', 'alice', fromAddr, toAddr, subject, content, 'alice'
);

// Insert into recipient's inbox
db.prepare('INSERT INTO ob_emails (email_id, username, from_address, to_address, subject, content, inbox_owner) VALUES (?, ?, ?, ?, ?, ?, ?)').run(
  'bob/' + subject + '.eml', 'bob', fromAddr, toAddr, subject, content, 'bob'
);

console.log('Email sent successfully.');

// Verify
const sent = db.prepare(\"SELECT email_id, from_address, to_address, subject FROM ob_emails WHERE subject = ?\").all(subject);
console.log(JSON.stringify(sent, null, 2));
"

